codeExample.bad:
/* A close icon rendered at only 16x16 pixels total clickable area,
   well under the 24x24 minimum, with nothing expanding the hit area */
.close-icon {
  width: 16px;
  height: 16px;
}

codeExample.good:
/* The icon graphic stays visually small, but padding expands the
   actual clickable area to meet the 24x24 pixel minimum */
.close-icon {
  width: 24px;
  height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.close-icon svg {
  width: 12px;
  height: 12px;
}
